export async function parallel(threads, items, fn) {
    return new Promise((resolve, reject) => {
        let busyThreads = 0;
        let failed = false;
        items = items.slice();
        let loop = () => {
            if (failed) {
                return;
            }
            if (!items.length) {
                if (busyThreads === 0) {
                    resolve();
                }
                return;
            }
            if (busyThreads >= threads) {
                return;
            }
            busyThreads++;
            fn(items.shift()).then(() => {
                busyThreads--;
                loop();
            }, (err) => {
                busyThreads--;
                failed = true;
                reject(err);
            });
            loop();
        };
        loop();
    });
}
